c.cpp:
class Solution {
public:
    int minimumOperations(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int cnt = 0;
        for (int i = 0; i < nums.size(); i++)
            if (nums[i] > 0 && (i == 0 || nums[i-1] != nums[i])) cnt++;
        return cnt;
    }
};

